import csv

# Search distances from Minneapolis to Ohio cities and between Ohio cities
def search_distances(origin, destination):
    with open('data/googleDistanceMatrix/distance.csv', 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            if (row['origin'].strip().lower() == origin.strip().lower() and
                row['destination'].strip().lower() == destination.strip().lower()):
                return {"origin": row['origin'], "destination": row['destination'],
                        "duration": row['duration'], "distance": row['distance']}
    return None

ohio_cities = ["Cleveland", "Columbus", "Cincinnati", "Toledo", "Dayton", "Akron"]

# Minneapolis to Ohio cities
print("=== Minneapolis to Ohio Cities ===")
for city in ohio_cities:
    r = search_distances("Minneapolis", city)
    if r:
        print(f"  Minneapolis -> {city}: {r['duration']}, {r['distance']}")
    else:
        print(f"  Minneapolis -> {city}: NOT FOUND")

# Between Ohio cities
print("\n=== Between Ohio Cities ===")
for i, c1 in enumerate(ohio_cities):
    for c2 in ohio_cities:
        if c1 != c2:
            r = search_distances(c1, c2)
            if r:
                print(f"  {c1} -> {c2}: {r['duration']}, {r['distance']}")

# Return routes
print("\n=== Ohio Cities to Minneapolis ===")
for city in ohio_cities:
    r = search_distances(city, "Minneapolis")
    if r:
        print(f"  {city} -> Minneapolis: {r['duration']}, {r['distance']}")
